export interface SendResult {
  ok: boolean;
  channel: string;
  error?: string;
}

export interface Channel {
  readonly name: string;
  send(to: string, subject: string, body: string): Promise<SendResult>;
}

export interface Notification {
  to: string;
  channel: string;
  templateId: string;
  vars: Record<string, string>;
}

files.server/templates.ts:
const TEMPLATES: Record<string, string> = {
  welcome: "Hello {{name}}, welcome aboard.",
  reset: "Hi {{name}}, use code {{code}} to reset your password.",
};

export function render(templateId: string, vars: Record<string, string>): string {
  const tpl = TEMPLATES[templateId];
  if (!tpl) {
    throw new Error(`unknown_template:${templateId}`);
  }
  return tpl.replace(/\{\{(\w+)\}\}/g, (_m, key) => vars[key] ?? "");
}

