import type { Channel, SendResult } from "../types";

export const emailChannel: Channel = {
  name: "email",
  async send(to, subject, body): Promise<SendResult> {
    if (!to.includes("@")) {
      return { ok: false, channel: "email", error: "invalid_address" };
    }
    // pretend to hand off to an SMTP client
    return { ok: true, channel: "email" };
  },
};

