import type { Notification, SendResult } from "./types";
import { emailChannel } from "./channels/email";
import { render } from "./templates";

const CHANNELS = [emailChannel];

export async function dispatch(n: Notification): Promise<SendResult> {
  const channel = CHANNELS.find((c) => c.name === n.channel);
  if (!channel) {
    return { ok: false, channel: n.channel, error: "unknown_channel" };
  }
  const body = render(n.templateId, n.vars);
  return channel.send(n.to, n.templateId, body);
}
